// Define the function
function generatePassword() {
  // Set local variables
  const passwordLength = 16;
  const includeCapitalLetters = 2;
  const includeSpecialCharacters = 1;

  // Define possible characters for each category
  const lowercaseLetters = "abcdefghijklmnopqrstuvwxyz";
  const uppercaseLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const specialCharacters = "!@#$%^&*()_+-=[]{}|;:,.<>?";
  const numbers = "0123456789";

  // Initialize the possible characters to use in the password
  let possibleCharacters = lowercaseLetters;

  // Add uppercase letters to possible characters if requested
  if (includeCapitalLetters > 0) {
    possibleCharacters += uppercaseLetters;
  }

  // Add special characters to possible characters if requested
  if (includeSpecialCharacters > 0) {
    possibleCharacters += specialCharacters;
  }

  // Generate the password
  let password = "";
  for (let i = 0; i < passwordLength; i++) {
    // Choose a random character from the possible characters
    const randomIndex = Math.floor(Math.random() * possibleCharacters.length);
    const randomCharacter = possibleCharacters[randomIndex];

    // Add the random character to the password
    password += randomCharacter;
  }

  // Return the generated password
  return password;
}

// Call the function and output the result to the console
console.log(generatePassword());
